// dto/create-user.dto.ts
import { IsEmail, IsString, IsInt, Min, IsOptional } from 'class-validator';

export class CreateUserDto {
  @IsEmail()
  email: string;

  @IsString()
  name: string;

  @IsInt()
  @Min(18)
  age: number;

  @IsOptional()
  @IsString()
  bio?: string;
}

// main.ts
import { ValidationPipe } from '@nestjs/common';
const app = await NestFactory.create(AppModule);
app.useGlobalPipes(
  new ValidationPipe({
    whitelist: true,            // strip undecorated props
    forbidNonWhitelisted: true, // 400 if any are present
    transform: true,            // DTO instance + primitive coercion
  }),
);
await app.listen(3000);

Key points: every field needs a decorator (a field with none is stripped by whitelist!); @IsOptional() must come before the type decorator on bio; class — not interface — so the metadata survives; the pipe is global so every endpoint is validated by default.

model.ru:
// dto/create-user.dto.ts
import { IsEmail, IsString, IsInt, Min, IsOptional } from 'class-validator';

export class CreateUserDto {
  @IsEmail()
  email: string;

  @IsString()
  name: string;

  @IsInt()
  @Min(18)
  age: number;

  @IsOptional()
  @IsString()
  bio?: string;
}

// main.ts
import { ValidationPipe } from '@nestjs/common';
const app = await NestFactory.create(AppModule);
app.useGlobalPipes(
  new ValidationPipe({
    whitelist: true,            // срезать недекорированные поля
    forbidNonWhitelisted: true, // 400, если они присутствуют
    transform: true,            // экземпляр DTO + приведение примитивов
  }),
);
await app.listen(3000);

Ключевое: каждому полю нужен декоратор (поле без декоратора срежет whitelist!); @IsOptional() должен идти перед декоратором типа на bio; класс — не интерфейс — чтобы метаданные пережили компиляцию; pipe глобальный, поэтому каждый эндпоинт валидируется по умолчанию.
